// sweepArticleInvite lists the live invites of this kind to an address.
func (a *Auth) sweepArticleInvite(ctx context.Context, address string, now time.Time) ([]*pendingInvite, error) {
	rows, err := a.db.Query(ctx, `SELECT `+models.ArticleInviteColumns+` FROM `+models.ArticleInviteTable+` WHERE "email" = $1 AND "expires_at" > $2`, address, now)
	if err != nil {
		return nil, err
	}
	invites, err := models.Collect(rows, models.ScanArticleInvite)
	if err != nil {
		return nil, err
	}
	found := make([]*pendingInvite, 0, len(invites))
	for _, invite := range invites {
		found = append(found, pendingArticleInvite(invite))
	}
	return found, nil
}

