// will be stored. Then, in order: the role ceiling, 409 for an address already invited or already a member, the
// row with the token's hash, the mail. The row is kept only if the mail was handed to the adapter. The token is
// answered only when emails are captured (tests).
func (a *Auth) IssueArticleInvite(ctx context.Context, session *Session, input models.Values, before func(models.Values) (models.Values, error)) (*models.ArticleInvite, *InviteDebug, error) {
	token := randomToken(32)
	me := session.User.ID
	draft := models.Values{}
	for key, value := range input {
		draft[key] = value
	}
	draft["email"] = inviteAddress(inviteText(draft["email"]))
	draft["invited_by"] = me
	draft["token_hash"] = hashToken(token)
	draft["expires_at"] = time.Now().Add(604800 * time.Second)
	values, err := before(draft)
	if err != nil {
		return nil, nil, err
	}
	values["email"] = inviteAddress(inviteText(values["email"]))
	values["invited_by"] = me
	values["token_hash"] = hashToken(token)
	parent := values["article_id"]
	waiting, err := models.ScanArticleInvite(a.db.QueryRow(ctx, `SELECT `+models.ArticleInviteColumns+` FROM `+models.ArticleInviteTable+` WHERE "article_id" = $1 AND "email" = $2`, parent, values["email"]))
	if err != nil && !errors.Is(err, pgx.ErrNoRows) {
		return nil, nil, err
	}
	if waiting != nil && waiting.ExpiresAt.After(time.Now()) {
		return nil, nil, httpx.NewError(http.StatusConflict, "invite_exists", "An invite to this address is already waiting")
	}
	var member bool
	err = a.db.QueryRow(ctx, `SELECT EXISTS (SELECT 1 FROM `+models.ArticleEditorTable+` m JOIN `+models.UserTable+` u ON u."id" = m."user_id" WHERE m."article_id" = $1 AND u."email" = $2)`, parent, values["email"]).Scan(&member)
	if err != nil {
		return nil, nil, err
	}
	if member {
		return nil, nil, httpx.NewError(http.StatusConflict, "already_member", "This address already belongs to a member")
	}
	name, found, err := a.nameOf(ctx, articleInviteNameQuery, parent)
	if err != nil {
		return nil, nil, err
	}
	if !found {
		return nil, nil, httpx.NewError(http.StatusBadRequest, "invalid_reference", "A referenced row does not exist")
	}
	inviter, _, err := a.nameOf(ctx, inviterNameQuery, me)
	if err != nil {
		return nil, nil, err
	}

	// A lapsed invite to the address gives way to the new one
	tx, err := a.db.Begin(ctx)
	if err != nil {
		return nil, nil, err
	}
	defer tx.Rollback(ctx)
	if waiting != nil {
		if _, err := tx.Exec(ctx, `DELETE FROM `+models.ArticleInviteTable+` WHERE "id" = $1`, waiting.ID); err != nil {
			return nil, nil, err
		}
	}
	sql, args := db.Insert(models.ArticleInviteTable, values, models.ArticleInviteColumns)
	row, err := models.ScanArticleInvite(tx.QueryRow(ctx, sql, args...))
	if err != nil {
		return nil, nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, nil, err
	}
	link := AppURL() + "/invite/" + url.PathEscape(token)
	if err := email.Send(ctx, email.Invite(row.Email, name, inviter, "", link, row.ExpiresAt)); err != nil {
		if _, gone := a.db.Exec(ctx, `DELETE FROM `+models.ArticleInviteTable+` WHERE "id" = $1`, row.ID); gone != nil {
			return nil, nil, gone
		}
		return nil, nil, err
	}
	if email.CurrentMode() != email.ModeCapture {
		return row, nil, nil
	}
	return row, &InviteDebug{Token: token, URL: link}, nil
}

// acceptArticleInvite makes the ArticleEditor an invite stands for and uses the invite up, in one transaction. A membership
// that exists already is left as it is. Nil when the invite was gone before this could take it.
func (a *Auth) acceptArticleInvite(ctx context.Context, user *models.User, invite *models.ArticleInvite) (*Accepted, error) {
	tx, err := a.db.Begin(ctx)
	if err != nil {
		return nil, err
	}
	defer tx.Rollback(ctx)
	used, err := tx.Exec(ctx, `DELETE FROM `+models.ArticleInviteTable+` WHERE "id" = $1`, invite.ID)
	if err != nil {
		return nil, err
	}
	if used.RowsAffected() == 0 {
		return nil, nil
	}
	if _, err := tx.Exec(ctx, `INSERT INTO `+models.ArticleEditorTable+` ("article_id", "user_id") VALUES ($1, $2) ON CONFLICT DO NOTHING`, invite.ArticleID, user.ID); err != nil {
		return nil, err
	}
	if err := tx.Commit(ctx); err != nil {
		return nil, err
	}
	return &Accepted{Entity: "Article", ID: invite.ArticleID, Tenant: nil}, nil
}

// inviteOf is the invite a token belongs to, lapsed or not. Nil when there is none.
func (a *Auth) inviteOf(ctx context.Context, token string) (*pendingInvite, error) {
	tokenHash := hashToken(token)
	if row, err := models.ScanArticleInvite(a.db.QueryRow(ctx, `SELECT `+models.ArticleInviteColumns+` FROM `+models.ArticleInviteTable+` WHERE "token_hash" = $1`, tokenHash)); err == nil {
		return pendingArticleInvite(row), nil
	} else if !errors.Is(err, pgx.ErrNoRows) {
		return nil, err
	}
	return nil, nil
}

// liveInvite is the token's invite: 404 for a token that is unknown, used or revoked, 410 for one that has lapsed.
func (a *Auth) liveInvite(ctx context.Context, token string) (*pendingInvite, error) {
	found, err := a.inviteOf(ctx, token)
	if err != nil {
		return nil, err
	}
	if found == nil {
		return nil, httpx.NotFound()
	}
	if !found.expiresAt.After(time.Now()) {
		return nil, httpx.NewError(http.StatusGone, "invite_expired", "This invite has expired")
	}
	return found, nil
}

// acceptFound accepts one invite, whichever membership it stands for.
func (a *Auth) acceptFound(ctx context.Context, user *models.User, found *pendingInvite) (*Accepted, error) {
	switch row := found.row.(type) {
	case *models.ArticleInvite:
		return a.acceptArticleInvite(ctx, user, row)
	}
	return nil, nil
}

// AcceptPending is the one place an invite becomes a membership. It does nothing unless the proven email is the
// account's own; then every live invite to that address is accepted, across all invited memberships. It answers
// what it accepted: the invite whose token was used first, then the others, oldest first.
func (a *Auth) AcceptPending(ctx context.Context, user *models.User, provenEmail string, usedToken string) ([]Accepted, error) {
	accepted := []Accepted{}
	address := inviteAddress(provenEmail)
	if address == "" || address != inviteAddress(user.Email) {
		return accepted, nil
	}
	now := time.Now()
	first := ""
	if usedToken != "" {
		first = hashToken(usedToken)
	}
	var live []*pendingInvite
	for _, sweep := range []func(context.Context, string, time.Time) ([]*pendingInvite, error){a.sweepArticleInvite} {
		found, err := sweep(ctx, address, now)
		if err != nil {
			return nil, err
		}
		live = append(live, found...)
	}
	sort.SliceStable(live, func(i, j int) bool {
		if (live[i].tokenHash == first) != (live[j].tokenHash == first) {
			return live[i].tokenHash == first
		}
		return live[i].createdAt.Before(live[j].createdAt)
	})
	for _, invite := range live {
		made, err := a.acceptFound(ctx, user, invite)
		if err != nil {
			return nil, err
		}
		if made != nil {
			accepted = append(accepted, *made)
		}
	}
	return accepted, nil
}

// acceptWithToken accepts for a password sign-in. A password proves nothing about a mailbox, so it accepts only
// with a live token for the account's own address.
func (a *Auth) acceptWithToken(ctx context.Context, user *models.User, token string) ([]Accepted, error) {
	found, err := a.inviteOf(ctx, token)
	if err != nil {
		return nil, err
	}
	if found == nil || !found.expiresAt.After(time.Now()) {
		return []Accepted{}, nil
	}
	return a.AcceptPending(ctx, user, found.email, token)
}

var inviteAcceptInput = validation.Object{Fields: []validation.Field{
	{Name: "password", Type: validation.String{MinLength: 8, MaxLength: 200}},
	{Name: "name", Required: true, Type: validation.String{MinLength: 1, MaxLength: 100}},
	{Name: "phone", Nullable: true, Type: validation.String{MaxLength: 40}},
	{Name: "preferences", Nullable: true, Type: validation.Shape{Keys: []validation.Key{
		{Name: "theme", Default: json.RawMessage("\"light\""), Type: validation.Enum{Values: []string{"light", "dark"}}},
		{Name: "digest", Default: json.RawMessage("true"), Type: validation.Boolean{}},
		{Name: "quiet_hours", Type: validation.Shape{Keys: []validation.Key{
			{Name: "from", Required: true, Type: validation.Integer{Min: validation.F(0), Max: validation.F(23)}},
			{Name: "to", Required: true, Type: validation.Integer{Min: validation.F(0), Max: validation.F(23)}},
		}}},
	}}},
}}

// Invite handles GET /api/auth/invites/{token}: what an invite offers, for its landing page. It never accepts:
// mail scanners open links.
func (a *Auth) Invite(c *gin.Context) {
	ctx := c.Request.Context()
	found, err := a.liveInvite(ctx, c.Param("token"))
	if err != nil {
		httpx.HandleError(c, err, "read")
		return
	}
	name, _, err := a.nameOf(ctx, found.nameQuery, found.parent)
	if err != nil {
		httpx.HandleError(c, err, "read")
		return
	}
	inviter, _, err := a.nameOf(ctx, inviterNameQuery, found.invitedBy)
	if err != nil {
		httpx.HandleError(c, err, "read")
		return
	}
	account, err := a.hasAccount(ctx, found.email)
	if err != nil {
		httpx.HandleError(c, err, "read")
		return
	}
	httpx.OK(c, inviteLookup{
		Entity:    found.entity,
		Name:      name,
		Role:      found.role,
		Inviter:   inviter,
		Email:     maskEmail(found.email),
		ExpiresAt: models.FormatDateTime(found.expiresAt),
		Account:   account,
	})
}

// InviteAccept handles POST /api/auth/invites/{token}/accept. A session under the invite's email accepts; one
// under another email is refused, and nothing changes. Without a session the token never signs anyone into an
// account that exists: it asks for a sign-in. Where the address has no account, the body creates it (the token
// has proven the address), and the reply signs it in.
func (a *Auth) InviteAccept(c *gin.Context) {
	ctx := c.Request.Context()
	token := c.Param("token")
	session, err := a.Session(c)
	if err != nil {
		httpx.HandleError(c, err, "write")
		return
	}
	found, err := a.liveInvite(ctx, token)
	if err != nil {
		httpx.HandleError(c, err, "write")
		return
	}
	if session != nil {
		me, err := models.ScanUser(a.db.QueryRow(ctx, `SELECT `+models.UserColumns+` FROM `+models.UserTable+` WHERE "id" = $1`, session.User.ID))
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			httpx.HandleError(c, err, "write")
			return
		}
		if err != nil || inviteAddress(me.Email) != found.email {
			httpx.Fail(c, httpx.NewError(http.StatusForbidden, "invite_email_mismatch", "This invite is for another address"))
			return
		}
		accepted, err := a.AcceptPending(ctx, me, found.email, token)
		if err != nil {
			httpx.HandleError(c, err, "write")
			return
		}
		httpx.JSON(c, http.StatusOK, signedIn{Data: models.PresentUser(session.row, a.see.Viewer(session)), Accepted: accepted})
		return
	}
	account, err := a.hasAccount(ctx, found.email)
	if err != nil {
		httpx.HandleError(c, err, "write")
		return
	}
	if account {
		httpx.Fail(c, httpx.NewError(http.StatusUnauthorized, "sign_in_required", "Sign in to accept this invite"))
		return
	}
	// A missing or unreadable body counts as an empty one: an account that needs no fields is made without one
	body, perr := httpx.ParseBody(c)
	if perr != nil && perr.Code == "invalid_json" {
		body, perr = map[string]json.RawMessage{}, nil
	}
	if perr != nil {
		httpx.Fail(c, perr)
		return
	}
	values, perr := inviteAcceptInput.Parse(body)
	if perr != nil {
		httpx.Fail(c, perr)
		return
	}
	if password, ok := values["password"].(string); ok && password != "" {
		hash, err := HashPassword(password)
		if err != nil {
			httpx.HandleError(c, err, "write")
			return
		}
		values["password_hash"] = hash
	}
	delete(values, "password")
	values["email"] = found.email
	sql, args := db.Insert(models.UserTable, values, models.UserColumns)
	created, err := models.ScanUser(a.db.QueryRow(ctx, sql, args...))
	if err != nil {
		httpx.HandleError(c, err, "write")
		return
	}
	accepted, err := a.AcceptPending(ctx, created, found.email, token)
	if err != nil {
		httpx.HandleError(c, err, "write")
		return
	}
	signIn(c, created)
	shown, ok := a.shown(c, created)
	if !ok {
		return
	}
	httpx.JSON(c, http.StatusCreated, signedIn{Data: shown, Accepted: accepted})
}
